-- CREATE TABLE ... PARTITION OF with options of the parent's columns and
-- table constraints (OptTypedTableElementList), as PostgreSQL's MergeAttributes
-- applies them.
CREATE TABLE pp (a int, b text, c int) PARTITION BY RANGE (a);
CREATE TABLE pp1 PARTITION OF pp (b WITH OPTIONS NOT NULL DEFAULT 'x', CONSTRAINT pp1_c CHECK (c > 0)) FOR VALUES FROM (0) TO (10);
CREATE TABLE pp2 PARTITION OF pp (c DEFAULT 7, PRIMARY KEY (a)) FOR VALUES FROM (10) TO (20);
CREATE TABLE pp3 PARTITION OF pp (CHECK (a > 25), b NOT NULL) FOR VALUES FROM (20) TO (30);
CREATE TABLE pp4 PARTITION OF pp (zz NOT NULL) FOR VALUES FROM (30) TO (40);
CREATE TABLE pp5 PARTITION OF pp (a WITH OPTIONS NOT NULL, a NOT NULL) FOR VALUES FROM (40) TO (50);
\d pp1
\d pp2
\d pp3
INSERT INTO pp1 (a, c) VALUES (1, 1);
INSERT INTO pp1 (a, c) VALUES (2, 0);
SELECT * FROM pp ORDER BY a;
DROP TABLE pp;
CREATE TABLE pq (a int, b text) PARTITION BY LIST (a);
CREATE TABLE pq1 PARTITION OF pq (a PRIMARY KEY, b UNIQUE) FOR VALUES IN (1);
CREATE TABLE pq2 PARTITION OF pq (CONSTRAINT pq2_b_nn b NOT NULL, UNIQUE (b)) FOR VALUES IN (2);
\d pq1
\d pq2
INSERT INTO pq VALUES (1, 'x'), (2, 'y');
INSERT INTO pq VALUES (1, 'z');
INSERT INTO pq VALUES (2, NULL);
DROP TABLE pq;
